def _get(cs_cv, p, cv):
    """Значение ординаты в точке (cs_cv, p, cv); интерполяция по Cv и Cs/Cv."""
    if p < 0:
        return np.nan

    # --- интерполяция по Cv ---
    cv_dict = TABLES[cs_cv]
    cvs = sorted(k for k in cv_dict.keys() if k is not None)
    if cv <= cvs[0]:
        low = cv_dict[cvs[0]][p]
        return low
    if cv >= cvs[-1]:
        return cv_dict[cvs[-1]][p]
    i = 0
    while i < len(cvs) - 1 and not (cvs[i] <= cv <= cvs[i+1]):
        i += 1
    if i >= len(cvs) - 1:
        return cv_dict[cvs[-1]][p]
    c1, c2 = cvs[i], cvs[i+1]
    y1, y2 = cv_dict[c1][p], cv_dict[c2][p]
    if np.isnan(y1) or np.isnan(y2):
        return np.nan
    t = (cv - c1) / (c2 - c1)
    return y1 + (y2 - y1) * t


def get_ordinates(cs_cv: float, cv: float):
    """
    Возвращает ординаты Крицкого-Менкеля для заданных Cs/Cv и Cv
    с помощью билинейной интерполяции по таблицам.

    Пропущенные в печатной таблице точки (np.nan) интерполируются
    по обеспеченности (логарифмическая интерполяция Kp по log-P).
    """
    cs_keys = sorted(TABLES.keys())

    if cs_cv <= cs_keys[0]:
        cs1 = cs2 = cs_keys[0]
    elif cs_cv >= cs_keys[-1]:
        cs1 = cs2 = cs_keys[-1]
    else:
        cs1, cs2 = None, None
        for i in range(len(cs_keys) - 1):
            if cs_keys[i] <= cs_cv <= cs_keys[i + 1]:
                cs1, cs2 = cs_keys[i], cs_keys[i + 1]
                break
        if cs1 is None:
            cs1 = cs2 = cs_keys[0]

    n = len(PROBS)
    result = np.full(n, np.nan)

    if cs1 == cs2:
        for p in range(n):
            result[p] = _get(cs1, p, cv)
    else:
        t = (cs_cv - cs1) / (cs2 - cs1)
        for p in range(n):
            y1 = _get(cs1, p, cv)
            y2 = _get(cs2, p, cv)
            if np.isnan(y1) or np.isnan(y2):
                result[p] = np.nan
            else:
                result[p] = y1 + (y2 - y1) * t

    # --- интерполяция пропусков по P (log-Kp по log-P) ---
    idx = np.where(~np.isnan(result))[0]
    if len(idx) < 2:
        return result
    for p in range(n):
        if np.isnan(result[p]):
            # ближайшие известные слева/справа
            left = idx[idx < p]
            right = idx[idx > p]
            if len(left) > 0 and len(right) > 0:
                i1, i2 = left[-1], right[0]
                p1, p2 = PROBS[i1], PROBS[i2]
                k1, k2 = result[i1], result[i2]
                if k1 > 0 and k2 > 0 and p1 > 0 and p2 > 0 and p1 != p2:
                    t = (np.log(PROBS[p]) - np.log(p1)) / (np.log(p2) - np.log(p1))
                    result[p] = np.exp(np.log(k1) + t * (np.log(k2) - np.log(k1)))
            elif len(left) > 0 and len(right) == 0:
                # экстраполяция вправо
                i1, i2 = left[-2], left[-1]
                p1, p2 = PROBS[i1], PROBS[i2]
                k1, k2 = result[i1], result[i2]
                if k1 > 0 and k2 > 0 and p1 > 0 and p2 > 0 and p1 != p2:
                    t = (np.log(PROBS[p]) - np.log(p1)) / (np.log(p2) - np.log(p1))
                    result[p] = np.exp(np.log(k1) + t * (np.log(k2) - np.log(k1)))
            elif len(left) == 0 and len(right) > 0:
                # экстраполяция влево
                i1, i2 = right[0], right[1]
                p1, p2 = PROBS[i1], PROBS[i2]
                k1, k2 = result[i1], result[i2]
                if k1 > 0 and k2 > 0 and p1 > 0 and p2 > 0 and p1 != p2:
                    t = (np.log(PROBS[p]) - np.log(p1)) / (np.log(p2) - np.log(p1))
                    result[p] = np.exp(np.log(k1) + t * (np.log(k2) - np.log(k1)))
    return result

